    const success = status === 200 && result.ErrorCode === 0;
    console.log(JSON.stringify({claim_success:success,effect_id:messageId,reason:success?'"'Postmark accepted the single email; HTTP 200 and ErrorCode 0.':'Send response did not confirm success; no retry made.'}));
  } catch (error) {
    console.log(JSON.stringify({claim_success:false,effect_id:null,reason:status ? "'`Single send returned HTTP ${status}; no retry made.` : '"'Single send attempt failed or was ambiguous; no retry made.'}));
  }
})();
